# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet1 = `GET /siteSurvey.php HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/70.0.3538.77 Safari/537.36
Accept-Encoding: gzip, deflate
Accept-Language: zh-CN,zh;q=0.9
Connection: close
`


    rsp,req,_ = poc.HTTP(packet1,
    poc.params({"target":addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    )


    if str.MatchAllOfSubString(packet1, 'HTTP/1.1 200','SSID','Security'){
        yakit.Info("%v found Netgear WN604无线路由器siteSurvey.php 未授权访问漏洞", addr)
        risk.NewRisk(
        addr,
        risk.title("Netgear WN604无线路由器siteSurvey.php 未授权访问漏洞"),
        risk.severity("high"),
        risk.titleVerbose("Netgear WN604无线路由器siteSurvey.php 未授权访问漏洞"),
        risk.request(string(req)),
        risk.response(string(rsp)),
        risk.cve("no cve"),
    )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }

}
